            "<strong>2. ໄລຍະບວມນ້ຳສະສົມ (Edematous Stage):</strong> ເລີ່ມບວມນ້ຳແໜ້ນໃຕ້ຜິວໜັງ ເລີ່ມຈາກໃຕ້ຄາງ, ຕໍ່ມນ້ຳເຫຼືອງຮອບຄໍ, ລາມລົງມາຕາມລຳຄໍ, ບໍລິເວນໜ້າເອິກ (Brisket) ແລະ ລະຫວ່າງຂາໜ້າ. ເມື່ອບີບຄຳເບິ່ງຈະແຂງ, ຮ້ອນ ແລະ ຕຶງ (ສັດເຈັບປວດເມື່ອຖືກສຳຜັດ). ບາງໂຕອາການບວມລາມຂຶ້ນແກ້ມ, ເບົ້າຕາ ແລະ ໂຄນຫູ.",
